using System;using System.Linq;using System.Collections.Generic;using System.IO;using Touchfish;
public static partial class RuleTests {
 static void FillSealed(SealedSession session,int seat){var view=session.View(seat);if(view.Phase=="class")session.Act(seat,view.Session,view.Revision,"class",view.Classes[0]);view=session.View(seat);if(view.Opened<18)session.Act(seat,view.Session,view.Revision,"open-all");view=session.View(seat);foreach(var p in view.Pool){for(int n=0;n<p.Value&&session.View(seat).Deck.Values.Sum()<30;n++){view=session.View(seat);session.Act(seat,view.Session,view.Revision,"edit",p.Key,1);}}}
 static void Sealed(){var session=new SealedSession(catalog,48001,matchRules.Supports);Check(session.View(0).Classes.Length==3&&session.View(0).Classes.Distinct().Count()==3,"Three private class choices");FillSealed(session,0);FillSealed(session,1);var a=session.View(0);var b=session.View(1);Check(a.Pool.Values.Sum()==90&&b.Pool.Values.Sum()==90&&a.Opened==18,"18 five-card packs produce exactly 90 cards per seat");Check(a.Pool.Keys.All(id=>{var c=catalog.Card(id);return (c.CardClass=="NEUTRAL"||c.CardClass==a.ClassId)&&c.Rarity!="FREE"&&matchRules.Supports(c);}),"Only supported pack-eligible class/neutral cards, no Basic cards or blocked Naxx effects");
  string first=a.Pool.Keys.First();a.Pool[first]=10000;a.Deck.Clear();a.LastPack[0].Id="corrupt";Check(session.View(0).Pool.Values.Sum()==90&&session.View(0).Deck.Values.Sum()==30&&session.View(0).LastPack.All(c=>c.Id!="corrupt"),"Views are detached from authority");
  bool invalid=false;try{session.Act(0,a.Session,a.Revision,"edit","not-opened",1);}catch(InvalidOperationException){invalid=true;}Check(invalid,"Reject unowned card without mutation");invalid=false;try{session.Act(0,a.Session,a.Revision-1,"confirm");}catch(InvalidOperationException){invalid=true;}Check(invalid,"Stale build actions rejected");
  a=session.View(0);session.Act(0,a.Session,a.Revision,"confirm");b=session.View(1);session.Act(1,b.Session,b.Revision,"confirm");Check(session.Ready,"Both players confirm valid thirty-card decks");var host=new LanHostGame(catalog,session.Deck(0),session.Deck(1),324,mode:GameModes.Sealed);Check(host.Game.Mode.Id=="sealed"&&LanProtocol.ReadView(catalog,host.Snapshot().State).Mode.Id=="sealed","Sealed mode survives authoritative public snapshot");
  var poolBefore=String.Join(",",session.View(0).Pool.Select(p=>p.Key+":"+p.Value));session.RecordResult(0);session.RecordResult(0);Check(session.Wins0==1,"One game result counted once");session.BeginRebuild();a=session.View(0);Check(a.Round==2&&!a.Confirmed&&!session.Ready&&a.Deck.Values.Sum()==30&&poolBefore==String.Join(",",a.Pool.Select(p=>p.Key+":"+p.Value)),"Between-game rebuild preserves original ninety-card pool and current thirty-card selection");foreach(int seat in new[]{0,1}){var v=session.View(seat);session.Act(seat,v.Session,v.Revision,"confirm");}session.RecordResult(0);Check(session.SeriesWinner==0&&session.Wins0==2,"Two wins finish series");
  var eligible=catalog.Deckable(catalog.Pool(session.PoolId)).Where(c=>matchRules.Supports(c)&&new[]{"COMMON","RARE","EPIC","LEGENDARY"}.Contains(c.Rarity));var generator=new SealedPackGenerator(eligible,91721);int normalLeg=0,normalEpic=0,normalCommons=0,legGap=0,epicGap=0;bool guarantees=true,firstTen=false;var counts=new Dictionary<string,int>();bool protectedCopies=true;const int packs=40000;
  for(int i=0;i<packs;i++){var pack=generator.Open();guarantees&=pack.Length==5&&pack.Any(c=>catalog.Card(c.Id).Rarity!="COMMON");bool legendary=pack.Any(c=>c.Quality=="normal"&&catalog.Card(c.Id).Rarity=="LEGENDARY"),epic=pack.Any(c=>c.Quality=="normal"&&catalog.Card(c.Id).Rarity=="EPIC");normalLeg+=legendary?1:0;normalEpic+=epic?1:0;normalCommons+=pack.Count(c=>c.Quality=="normal"&&catalog.Card(c.Id).Rarity=="COMMON");legGap=legendary?0:legGap+1;epicGap=epic?0:epicGap+1;guarantees&=legGap<40&&epicGap<10;if(i<10&&legendary)firstTen=true;if(i<18)foreach(var c in pack){var card=catalog.Card(c.Id);int seen;counts.TryGetValue(c.Id,out seen);int cap=card.Rarity=="LEGENDARY"?1:2;if(seen>=cap)protectedCopies&=eligible.Where(x=>x.Rarity==card.Rarity).All(x=>counts.ContainsKey(x.Id)&&counts[x.Id]>=cap);counts[c.Id]=seen+1;}}
  Check(guarantees&&firstTen,"Every pack five cards with Rare+, first-ten Legendary and long-run forty/ten hard pity");Check(protectedCopies,"Duplicate protection respects one Legendary / two other copies until rarity exhausted");Check(Math.Abs((double)normalLeg/packs-.054738)<.004&&Math.Abs((double)normalEpic/packs-.217663)<.008&&Math.Abs((double)normalCommons/packs-3.5)<.04,"Long-run sample agrees with published Normal Legendary/Epic means and 3.5 normal Commons");Console.WriteLine("Pack sample: "+normalLeg+" normal Legendary; "+normalEpic+" normal Epic; "+normalCommons+" normal Common / "+packs+" packs");
 }
